    "stem": "A 24-year-old man attends the surgical and medical outpatient department (OPD) of Mayo Hospital Lahore with clinical findings indicative of CPSP Pediatrics Acute Glomerulonephritis Post-Streptococcal Fluid and Salt Restriction. Clinical examination and investigative review confirm fluid restriction to insensible losses plus urine output, loop diuretic furosemide, and oral amlodipine for hypertension. Vitals reveal blood pressure of 126/82 mm Hg, heart rate of 80/min, respiratory rate of 16/min, and temperature of 37.8C (98.3F). Diagnostic serum testing, focused physiological assessment, and targeted structural evaluations demonstrate characteristic pathophysiological hallmarks of cpsp pediatrics acute glomerulonephritis post-streptococcal fluid and salt restriction. What is the most definitive diagnostic investigation or guideline-directed intervention indicated for this patient?",
